CREATE TABLE workflow_runs (
 id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY,
 tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 workflow_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 owner_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 conversation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
 turn_number INTEGER CHECK(turn_number BETWEEN 1 AND 10000),
 version_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
 draft_revision BIGINT CHECK(draft_revision BETWEEN 1 AND 9007199254740991),
 execution_authority CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 membership_authority CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 requested_audience VARCHAR(6) NOT NULL CHECK(requested_audience IN('portal','admin')),
 graph_snapshot JSON NOT NULL CHECK(JSON_TYPE(graph_snapshot)='OBJECT' AND OCTET_LENGTH(CAST(graph_snapshot AS CHAR CHARACTER SET utf8mb4))<=1048576),
 graph_sha256 VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL CHECK(REGEXP_LIKE(graph_sha256,_ascii'^[a-f0-9]{64}$','c')),
 state VARCHAR(16) NOT NULL CHECK(state IN('pending','running','succeeded','failed','cancelled','interrupted')),
 question MEDIUMTEXT NOT NULL CHECK(OCTET_LENGTH(question) BETWEEN 1 AND 32768),
 answer MEDIUMTEXT CONSTRAINT workflow_answer_bytes CHECK(OCTET_LENGTH(answer)<=1048576),
 evidence JSON CHECK(evidence IS NULL OR JSON_TYPE(evidence)='OBJECT'),
 alias_snapshot JSON CHECK(alias_snapshot IS NULL OR JSON_TYPE(alias_snapshot)='OBJECT'),
 `usage` JSON CHECK(`usage` IS NULL OR JSON_TYPE(`usage`)='OBJECT'),
 error_code VARCHAR(100),
 process_owner CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
 lease_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
 lease_expires_at DATETIME(6),
 deadline_at DATETIME(6) NOT NULL,
 cancellation_requested_at DATETIME(6),
 created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 started_at DATETIME(6),
 finished_at DATETIME(6),
 active_conversation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS(CASE WHEN conversation_id IS NOT NULL AND state IN('pending','running') THEN conversation_id ELSE NULL END) STORED,
 UNIQUE(tenant_id,workspace_id,workflow_id,id),
 CONSTRAINT workflow_run_recipient_identity UNIQUE(tenant_id,workspace_id,workflow_id,id,owner_id),
 UNIQUE(conversation_id,turn_number),
 UNIQUE KEY workflow_one_active_turn_idx(active_conversation_id),
 KEY workflow_active_workspace_idx(tenant_id,workspace_id,state,lease_expires_at),
 KEY workflow_run_page_idx(tenant_id,workspace_id,owner_id,created_at DESC,id DESC),
 FOREIGN KEY(owner_id) REFERENCES users(id),
 FOREIGN KEY(tenant_id,workspace_id,workflow_id) REFERENCES workflows(tenant_id,workspace_id,id),
 FOREIGN KEY(tenant_id,workspace_id,workflow_id,version_id) REFERENCES workflow_versions(tenant_id,workspace_id,workflow_id,id),
 FOREIGN KEY(tenant_id,workspace_id,workflow_id,conversation_id,owner_id,version_id) REFERENCES workflow_conversations(tenant_id,workspace_id,workflow_id,id,owner_id,version_id),
 CHECK((version_id IS NOT NULL AND draft_revision IS NULL AND conversation_id IS NOT NULL AND turn_number IS NOT NULL) OR (version_id IS NULL AND draft_revision IS NOT NULL AND conversation_id IS NULL AND turn_number IS NULL)),
 CHECK((state IN('pending','running') AND finished_at IS NULL) OR (state NOT IN('pending','running') AND finished_at IS NOT NULL)),
 CONSTRAINT workflow_non_success_result_absent CHECK(state='succeeded' OR answer IS NULL),
 CONSTRAINT workflow_success_result_required CHECK(state<>'succeeded' OR (answer IS NOT NULL AND evidence IS NOT NULL AND alias_snapshot IS NOT NULL AND `usage` IS NOT NULL AND error_code IS NULL)),
 CHECK((state='running' AND process_owner IS NOT NULL AND lease_id IS NOT NULL AND lease_expires_at IS NOT NULL AND started_at IS NOT NULL) OR (state<>'running' AND process_owner IS NULL AND lease_id IS NULL AND lease_expires_at IS NULL)),
 CONSTRAINT workflow_runs_id_canonical CHECK(REGEXP_LIKE(id,_ascii'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT workflow_runs_tenant_id_canonical CHECK(REGEXP_LIKE(tenant_id,_ascii'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT workflow_runs_workspace_id_canonical CHECK(REGEXP_LIKE(workspace_id,_ascii'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT workflow_runs_workflow_id_canonical CHECK(REGEXP_LIKE(workflow_id,_ascii'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT workflow_runs_owner_id_canonical CHECK(REGEXP_LIKE(owner_id,_ascii'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT workflow_runs_conversation_id_canonical CHECK(conversation_id IS NULL OR REGEXP_LIKE(conversation_id,_ascii'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT workflow_runs_version_id_canonical CHECK(version_id IS NULL OR REGEXP_LIKE(version_id,_ascii'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT workflow_runs_execution_authority_canonical CHECK(REGEXP_LIKE(execution_authority,_ascii'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT workflow_runs_membership_authority_canonical CHECK(REGEXP_LIKE(membership_authority,_ascii'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT workflow_runs_process_owner_canonical CHECK(process_owner IS NULL OR REGEXP_LIKE(process_owner,_ascii'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT workflow_runs_lease_id_canonical CHECK(lease_id IS NULL OR REGEXP_LIKE(lease_id,_ascii'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
